const body = $input.first().json.body || $input.first().json;
const baseUrl = ($env.VOICEAI_BASE_URL || 'http://voiceai-server:3001').replace(/\/+$/, '');
const defaultClinicId = $env.VOICEAI_CLINIC_ID || 'auto';
const secret = $env.VOICEAI_N8N_SECRET || '';

const res = await fetch(`${baseUrl}/api/whatsapp/n8n-webhook/${encodeURIComponent(defaultClinicId)}`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    ...(secret ? { 'X-Webhook-Secret': secret } : {})
  },
  body: JSON.stringify(body)
});
const data = await res.json().catch(() => ({}));
return [{ json: { status: res.status, response: data } }];
